[metadata] {"type": "create", "filePath": "/app/src/main/java/ai/unifiedprocess/petclinic/vet/ui/VeterinariansView.java", "content": "package ai.unifiedprocess.petclinic.vet.ui;

import ai.unifiedprocess.petclinic.core.ui.MainLayout;
import ai.unifiedprocess.petclinic.vet.domain.Specialty;
import ai.unifiedprocess.petclinic.vet.domain.Vet;
import ai.unifiedprocess.petclinic.vet.domain.VetRepository;
import com.vaadin.flow.component.grid.Grid;
import com.vaadin.flow.component.orderedlayout.VerticalLayout;
import com.vaadin.flow.data.provider.DataProvider;
import com.vaadin.flow.router.PageTitle;
import com.vaadin.flow.router.Route;

import static java.util.stream.Collectors.joining;

/**
 * UC-002: View Veterinarians.
 *
 * Root of {@code /vets}. A grid of the clinic's veterinarians with their specialties,
 * fetched from the repository as the visitor scrolls (BR-001). The shell and the
 * navigation menu are rendered by {@link MainLayout}.
 */
@Route(value = "vets", layout = MainLayout.class)
@PageTitle("Veterinarians")
public class VeterinariansView extends VerticalLayout {

    private final transient VetRepository repository;

    public VeterinariansView(VetRepository repository) {
        this.repository = repository;

        Grid<Vet> grid = new Grid<>();
        grid.addColumn(Vet::firstName).setHeader("First name");
        grid.addColumn(Vet::lastName).setHeader("Last name");
        grid.addColumn(VeterinariansView::specialtiesOf).setHeader("Specialties");
        grid.setItems(DataProvider.fromCallbacks(
                query -> this.repository.findPage(query.getOffset(), query.getLimit()),
                query -> this.repository.count()));
        grid.setSizeFull();

        setSizeFull();
        add(grid);
    }

    /** The repository already delivers the names in order (GR-003), so the view only joins them. */
    private static String specialtiesOf(Vet vet) {
        return vet.specialties().isEmpty()
                ? "none"
                : vet.specialties().stream().map(Specialty::name).collect(joining(", "));
    }
}
