+import static org.junit.jupiter.api.Assertions.assertEquals;
+import static org.junit.jupiter.api.Assertions.assertInstanceOf;
+import static org.junit.jupiter.api.Assertions.assertTrue;
+
+/**
+ * UC-002: View Veterinarians.
+ */
+class UC002ViewVeterinariansTest extends PetClinicTestBase {
+
+    @Autowired
+    private DSLContext dsl;
+
+    @Autowired
+    private VetRepository repository;
+
+    @Test
+    @UseCase(id = "UC-002")
+    void gridListsEveryVeterinarianWithTheirSpecialties() {
+        assertDoesNotThrow(() -> navigate(VeterinariansView.class),
+                "Expected /vets to resolve to VeterinariansView without error");
+        assertEquals("vets", assertDoesNotThrow(
+                () -> find(SideNavItem.class).withPropertyValue(SideNavItem::getLabel, "Veterinarians").single(),
+                "Missing Veterinarians navigation item").getPath());
+
+        assertEquals(List.of(
+                "James | Carter | none",
+                "Helen | Leary | radiology",
+                "Linda | Douglas | dentistry, surgery",
+                "Rafael | Ortega | surgery",
+                "Henry | Stevens | radiology",
+                "Sharon | Jenkins | none"), renderedRows());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", scenario = "A1: No Veterinarians Registered")
+    void emptyDirectoryRendersGridWithNoRows() {
+        dsl.deleteFrom(VET_SPECIALTIES).execute();
+        dsl.deleteFrom(VETS).execute();
+
+        navigate(VeterinariansView.class);
+
+        assertEquals(List.of(), renderedRows());
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-001")
+    void gridFetchesVeterinariansOneChunkAtATime() {
+        navigate(VeterinariansView.class);
+
+        Grid<Vet> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+        assertInstanceOf(BackEndDataProvider.class, grid.getDataProvider(),
+                "Expected the grid to fetch its rows from the repository as the user scrolls");
+
+        assertEquals(6, repository.count());
+        assertEquals(List.of("James", "Helen"), firstNames(repository.findPage(0, 2)));
+        assertEquals(List.of("Linda", "Rafael"), firstNames(repository.findPage(2, 2)));
+        assertEquals(List.of("Henry", "Sharon"), firstNames(repository.findPage(4, 2)));
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-002")
+    void specialtiesOfAVetAreListedAlphabetically() {
+        navigate(VeterinariansView.class);
+
+        // Seeded as surgery, then dentistry: the list is by name, not by insertion.
+        assertTrue(renderedRows().contains("Linda | Douglas | dentistry, surgery"),
+                "Expected Linda Douglas's specialties alphabetically: dentistry, surgery");
+    }
+
+    @Test
+    @UseCase(id = "UC-002", businessRules = "BR-003")
+    void veterinariansAreVisibleWithoutLogin() {
+        // No authentication is performed, covering BR-003 (Anonymous Access).
+        assertDoesNotThrow(() -> navigate(VeterinariansView.class),
+                "Expected /vets to render for an anonymous visitor");
+        assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected the veterinarians grid without logging in");
+    }
+
+    /** One line per rendered row, as the visitor reads it: first name, last name, specialties. */
+    private List<String> renderedRows() {
+        Grid<Vet> grid = assertDoesNotThrow(() -> find(Grid.class).single(),
+                "Expected exactly one veterinarians grid");
+        var tester = test(grid);
+        return IntStream.range(0, tester.size())
+                .mapToObj(row -> String.join(" | ",
+                        tester.getCellText(row, 0), tester.getCellText(row, 1), tester.getCellText(row, 2)))
+                .toList();
+    }
+
+    private static List<String> firstNames(Stream<Vet> vets) {
+        return vets.map(Vet::firstName).toList();
+    }
+}
